/**
 * The Analysis tab's list card -- one `StockPreview` per tracked symbol. `PulseCard(SYNTHESIS)`
 * per the spec (this card leads with `plain_read`, an AI-generated interpretation of the day's
 * data, not a raw reading), with the same glyph+title treatment `DashboardScreen`'s Technical
 * Briefing card and `SummaryScreen`'s header already use for AI-authored content -- sized to the
 * symbol text's own font size rather than a fixed icon dimension, so it scales with the title.
 *
 * Field-to-element mapping follows the spec's table exactly: symbol/name left, price/change pill
 * right, `plain_read` prose body, a muted `technical_setup` + chip-delta line, the top-4 condition
 * chips, and (only when `hasDirectNews` is true) a small NEWS footer line. A vertical `Spacer`
 * sized to `stock_preview_sparkline_space` sits under the price block -- the preview payload has
 * no chart series yet, so this reserves the sparkline's footprint without rendering anything, per
 * the spec's explicit "reserve space, don't render a placeholder" instruction.
 */
@Composable
fun StockPreviewCard(
    preview: StockPreview,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val pulseColors = LocalPulseColors.current

    PulseCard(
        style = PulseCardStyle.SYNTHESIS,
        modifier = modifier.fillMaxWidth(),
        onClick = onClick
    ) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        val symbolStyle = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold)
                        val glyphSize = with(LocalDensity.current) { symbolStyle.fontSize.toDp() }

                        Icon(
                            painter = painterResource(id = R.drawable.ic_engine_ai_sparkles),
                            contentDescription = stringResource(id = R.string.stock_analysis_ai_glyph_content_description),
                            tint = pulseColors.accentPrimary,
                            modifier = Modifier.size(glyphSize)
                        )
                        Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_small)))
                        Text(
                            text = preview.symbol,
                            style = symbolStyle,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                    preview.name?.let { name ->
                        Text(
                            text = name,
                            style = MaterialTheme.typography.bodySmall,
                            color = pulseColors.onSurfaceMuted,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }

                Column(horizontalAlignment = Alignment.End) {
                    preview.price?.let { price ->
                        Text(
                            text = "$${String.format(Locale.US, "%.2f", price)}",
                            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                    preview.changePercent?.let { changePercent ->
                        Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_small)))
                        val direction = when {
                            changePercent > 0 -> ChangeDirection.UP
                            changePercent < 0 -> ChangeDirection.DOWN
                            else -> ChangeDirection.FLAT
                        }
                        val (pillColor, textColor) = when (direction) {
                            ChangeDirection.UP -> pulseColors.signalBullishPill to pulseColors.signalBullishText
                            ChangeDirection.DOWN -> pulseColors.signalBearishPill to pulseColors.signalBearishText
                            ChangeDirection.FLAT -> pulseColors.signalNeutralPill to pulseColors.signalNeutralText
                        }
                        DirectionalChangePill(
                            changeText = "${String.format(Locale.US, "%.2f", abs(changePercent))}%",
                            direction = direction,
                            pillColor = pillColor,
                            contentColor = textColor
                        )
                    }
                    // TODO: add a sparkline later here
                    Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                }
            }

            preview.plainRead?.let { plainRead ->
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                Text(
                    text = plainRead,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }

            val chipsDeltaText = chipsDeltaText(added = preview.chipsAdded, removed = preview.chipsRemoved)
            if (preview.technicalSetup != null || chipsDeltaText != null) {
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    preview.technicalSetup?.let { setup ->
                        Text(
                            text = setup.replace('_', ' '),
                            style = MaterialTheme.typography.labelSmall,
                            color = pulseColors.onSurfaceMuted
                        )
                    }
                    if (preview.technicalSetup != null && chipsDeltaText != null) {
                        Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_medium)))
                    }
                    chipsDeltaText?.let { text ->
                        Text(
                            text = text,
                            style = MaterialTheme.typography.labelSmall,
                            color = pulseColors.onSurfaceMuted
                        )
                    }
                }
            }

            val previewChips = preview.conditionChips?.let { chips ->
                selectPreviewChips(chips = chips, added = preview.chipsAdded.orEmpty().toSet())
            }
            if (!previewChips.isNullOrEmpty()) {
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                ConditionChipRow(chips = previewChips)
            }

            if (preview.hasDirectNews == true && preview.topHeadline != null) {
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                HorizontalDivider(
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f),
                    thickness = dimensionResource(id = R.dimen.border_thin)
                )
                Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        text = stringResource(id = R.string.stock_analysis_news_label),
                        style = MaterialTheme.typography.labelSmall.copy(fontWeight = FontWeight.Bold),
                        color = pulseColors.onSurfaceMuted
                    )
                    Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_large)))
                    Text(
                        text = preview.topHeadline,
                        style = MaterialTheme.typography.bodySmall,
                        color = pulseColors.onSurfaceMuted,
                        modifier = Modifier.weight(1f)
                    )
                }
            }
        }
    }
}

/**
 * `null` when there's nothing to say (both lists empty/null) so the caller can skip the whole
 * metadata row rather than rendering an empty string.
 */
@Composable
private fun chipsDeltaText(added: List<String>?, removed: List<String>?): String? {
    val addedCount = added?.size ?: 0
    val removedCount = removed?.size ?: 0

    return when {
        addedCount > 0 && removedCount > 0 ->
            stringResource(id = R.string.stock_analysis_chips_new_and_dropped, addedCount, removedCount)
        addedCount > 0 ->
            stringResource(id = R.string.stock_analysis_chips_new_only, addedCount)
        removedCount > 0 ->
            stringResource(id = R.string.stock_analysis_chips_dropped_only, removedCount)
        else -> null
    }
}

